import React, { useState, useEffect } from "react"
import axios from "axios"

const SearchBar = () => {
  const [searchTerm, setSearchTerm] = useState("")
  const [searchResults, setSearchResults] = useState([])

  useEffect(() => {
    // Function to fetch data based on the search term
    const fetchSearchResults = async () => {
      try {
        // Make an API request to retrieve search results
        const response = await axios.get(`http://localhost:8800/members?search=${searchTerm}`)
        setSearchResults(response.data);
      } catch (error) {
        console.error("Error fetching search results:", error)
      }
    }

    // Call the function when searchTerm changes
    fetchSearchResults()
  }, [searchTerm])

  const handleInputChange = (e) => {
    setSearchTerm(e.target.value)
  }

  return (
    <div>
      <input
        type="text"
        placeholder="Search members..."
        value={search}
        onChange={handleInputChange}
      />
      <ul>
        {searchResults.map((result) => (
          <li key={result.id}>{`${result.firstname} ${result.lastname}`}</li>
        ))}
      </ul>
    </div>
  )
}

export default SearchBar
